import {league,stats} from './engine.js';
import {candidates,previews,raidRating,rankingTable} from './ratings.js';
import {legalMoves,inferLevel} from './observation.js';
self.onmessage=({data:{id,db,p,iv,trainer=40,observed,shadow=false,purified=false,lucky=false,fast,charged,threshold=90,cpFloor=.9,mode,cap}})=>{try{const max=50;if(mode==='table'){postMessage({id,result:rankingTable(db,p,cap,max)});return}const state={shadow,purified,lucky},moves=legalMoves(db,p,state);if(fast&&!moves.fast.includes(fast)||charged&&!moves.charged.includes(charged))throw Error('이 종·폼·분류가 보유할 수 없는 기술입니다.');const inference=inferLevel(db,p,iv,trainer,observed,state),level=inference.level,minLevel=inference.levels[0]||(purified?25:1),rows=candidates(db,p,iv,max,shadow,cpFloor,minLevel);if(purified)rows.forEach(c=>c.state='purified');if(mode==='preview'){postMessage({id,result:{previews:previews(rows,threshold).map(({name,cap,state,percentile})=>({name,cap,state,percentile}))}});return}const valid={...p,...moves},raid=raidRating(db,valid,iv,level,shadow,fast,charged);if(inference.status==='range'&&fast&&charged){const low=raidRating(db,valid,iv,inference.levels[0],shadow,fast,charged).current,high=raidRating(db,valid,iv,inference.levels.at(-1),shadow,fast,charged).current;if(low&&high)raid.currentRange={low:low.dps,high:high.dps}}postMessage({id,result:{iv:iv.reduce((a,b)=>a+b,0)/45*100,inference,leagues:p.mega?[]:[1500,2500,Infinity].map(cap=>league(db,p,iv,cap,max)),current:level?stats(db,p,iv,level):null,candidates:rows,previews:previews(rows,threshold),raid}})}catch(e){postMessage({id,error:e.message})}};
